<script>
(function () {
  var c = document.getElementById('net');
  if (!c || !c.getContext) return;
  var ctx = c.getContext('2d');
  var host = c.parentElement;
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var w = 0, h = 0, dpr = 1, nodes = [], raf = null;
  function colors() {
    var cs = getComputedStyle(document.documentElement);
    return { node:(cs.getPropertyValue('--accent')||'#B37D22').trim(), link:(cs.getPropertyValue('--ink-soft')||'#47536B').trim() };
  }
  function hexA(hex, a) {
    hex = hex.replace('#','');
    if (hex.length === 3) hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
    var n = parseInt(hex, 16);
    return 'rgba(' + ((n>>16)&255) + ',' + ((n>>8)&255) + ',' + (n&255) + ',' + a + ')';
  }
  function pseudo(n) { var x = Math.sin(n*127.1+311.7)*43758.5453; return x - Math.floor(x); }
  function build() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = host.clientWidth; h = host.clientHeight;
    c.width = w*dpr; c.height = h*dpr; c.style.width = w+'px'; c.style.height = h+'px';
    ctx.setTransform(dpr,0,0,dpr,0,0);
    var target = Math.max(14, Math.min(52, Math.round(w*h/16000)));
    nodes = [];
    for (var i=0;i<target;i++) nodes.push({ x:pseudo(i*1.3+0.7)*w, y:pseudo(i*2.7+1.9)*h, vx:(pseudo(i*3.1+0.2)-0.5)*0.18, vy:(pseudo(i*4.9+0.5)-0.5)*0.18, r:1.2+pseudo(i*5.5)*1.6 });
  }
  function draw() {
    var col = colors(), D = 132;
    ctx.clearRect(0,0,w,h);
    for (var i=0;i<nodes.length;i++) { var a=nodes[i];
      for (var j=i+1;j<nodes.length;j++) { var b=nodes[j], dx=a.x-b.x, dy=a.y-b.y, d=Math.sqrt(dx*dx+dy*dy);
        if (d<D) { ctx.strokeStyle=hexA(col.link,(1-d/D)*0.16); ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y); ctx.stroke(); } } }
    for (var k=0;k<nodes.length;k++) { var p=nodes[k]; ctx.fillStyle=hexA(col.node,0.5); ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,6.2832); ctx.fill(); }
  }
  function step() {
    for (var i=0;i<nodes.length;i++) { var a=nodes[i]; a.x+=a.vx; a.y+=a.vy;
      if (a.x<-12) a.x=w+12; else if (a.x>w+12) a.x=-12;
      if (a.y<-12) a.y=h+12; else if (a.y>h+12) a.y=-12; }
    draw(); raf = requestAnimationFrame(step);
  }
  build(); if (reduce) draw(); else step();
  var t;
  window.addEventListener('resize', function () { clearTimeout(t); t = setTimeout(function () { if (raf) cancelAnimationFrame(raf); build(); if (reduce) draw(); else step(); }, 160); });
})();
</script>
