<title>LT 2010 · Computer Skills for the Information Age</title>
<style>
  :root {
    --paper:#FAF9F6; --surface:#FFFFFF; --surface-2:#F1F2F0;
    --ink:#181D26; --ink-soft:#4A5261; --ink-faint:#79808E;
    --navy:#1C2A44; --accent:#B4741C; --accent-ink:#8A5713; --accent-bg:#F4EBDA;
    --line:#E3E2DC; --line-soft:#EDEDE8;
    --shadow:0 1px 2px rgba(24,29,38,.04),0 10px 30px rgba(24,29,38,.06);
    --shadow-sm:0 1px 2px rgba(24,29,38,.05);
    --serif:"Iowan Old Style","Charter","Palatino Linotype",Palatino,"Book Antiqua",Georgia,Cambria,serif;
    --sans:-apple-system,BlinkMacSystemFont,"Segoe UI","Helvetica Neue",Arial,sans-serif;
    --mono:ui-monospace,"SF Mono","SFMono-Regular",Menlo,Monaco,"Cascadia Code",Consolas,monospace;
    --measure:64ch; --pad:clamp(1.25rem,5vw,3rem);
    --r-card:10px; --r-sm:5px;
    --gutter:140px;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --paper:#0F141D; --surface:#161D2A; --surface-2:#1C2534;
      --ink:#EAECEF; --ink-soft:#A8B0BE; --ink-faint:#79839A;
      --navy:#C7D2E6; --accent:#DBA24A; --accent-ink:#E6BC72; --accent-bg:#241C10;
      --line:#28313F; --line-soft:#1E2632;
      --shadow:0 1px 2px rgba(0,0,0,.25),0 12px 32px rgba(0,0,0,.38);
      --shadow-sm:0 1px 2px rgba(0,0,0,.3);
    }
  }
  :root[data-theme="light"] {
    --paper:#FAF9F6; --surface:#FFFFFF; --surface-2:#F1F2F0;
    --ink:#181D26; --ink-soft:#4A5261; --ink-faint:#79808E;
    --navy:#1C2A44; --accent:#B4741C; --accent-ink:#8A5713; --accent-bg:#F4EBDA;
    --line:#E3E2DC; --line-soft:#EDEDE8;
    --shadow:0 1px 2px rgba(24,29,38,.04),0 10px 30px rgba(24,29,38,.06); --shadow-sm:0 1px 2px rgba(24,29,38,.05);
  }
  :root[data-theme="dark"] {
    --paper:#0F141D; --surface:#161D2A; --surface-2:#1C2534;
    --ink:#EAECEF; --ink-soft:#A8B0BE; --ink-faint:#79839A;
    --navy:#C7D2E6; --accent:#DBA24A; --accent-ink:#E6BC72; --accent-bg:#241C10;
    --line:#28313F; --line-soft:#1E2632;
    --shadow:0 1px 2px rgba(0,0,0,.25),0 12px 32px rgba(0,0,0,.38); --shadow-sm:0 1px 2px rgba(0,0,0,.3);
  }

  * { box-sizing:border-box; }
  html { scroll-behavior:smooth; }
  body { margin:0; background:var(--paper); color:var(--ink); font-family:var(--sans); font-size:17px; line-height:1.62; -webkit-font-smoothing:antialiased; text-rendering:optimizeLegibility; }
  ::selection { background:var(--accent-bg); color:var(--accent-ink); }
  a { color:inherit; }
  h1,h2,h3 { font-family:var(--serif); font-weight:600; text-wrap:balance; letter-spacing:-.015em; }

  .wrap { max-width:1120px; margin-inline:auto; padding-inline:var(--pad); }
  .ic { width:1.1em; height:1.1em; flex:none; display:inline-block; vertical-align:middle; color:var(--ink-soft); }
  .ic-lg { width:21px; height:21px; }
  #sprite { position:absolute; width:0; height:0; overflow:hidden; }

  /* ---------- nav ---------- */
  header.nav { position:sticky; top:0; z-index:50; background:color-mix(in srgb,var(--paper) 85%,transparent); backdrop-filter:saturate(1.3) blur(12px); -webkit-backdrop-filter:saturate(1.3) blur(12px); border-bottom:1px solid var(--line); }
  .nav-inner { max-width:1120px; margin-inline:auto; padding:.6rem var(--pad); display:flex; align-items:center; gap:1.5rem; }
  .brand { display:flex; align-items:center; gap:.6rem; margin-right:auto; }
  .brand .code { font-family:var(--mono); font-weight:600; font-size:.72rem; letter-spacing:.14em; color:#1a1206; background:var(--accent); border-radius:4px; padding:.24rem .45rem; }
  .brand .name { font-family:var(--serif); font-size:1.02rem; font-weight:600; }
  @media (max-width:560px) { .brand .name { display:none; } }
  .nav-links { display:flex; gap:1.25rem; align-items:center; }
  .nav-links a { text-decoration:none; color:var(--ink-soft); font-family:var(--mono); font-size:.78rem; letter-spacing:.04em; padding:.2rem 0; position:relative; transition:color .15s ease; }
  .nav-links a .no { color:var(--accent-ink); }
  .nav-links a::after { content:""; position:absolute; left:0; right:100%; bottom:-.2rem; height:1.5px; background:var(--accent); transition:right .2s ease; }
  .nav-links a:hover { color:var(--ink); }
  .nav-links a:hover::after { right:0; }
  .nav-links a:focus-visible { outline:2px solid var(--accent); outline-offset:4px; border-radius:2px; }
  @media (max-width:820px) { .nav-links { display:none; } }

  /* ---------- hero / cover ---------- */
  .hero { padding:clamp(2.75rem,7vw,5rem) 0 clamp(2.5rem,6vw,4rem); }
  .topmatter { font-family:var(--mono); font-size:.72rem; letter-spacing:.16em; text-transform:uppercase; color:var(--ink-faint); display:flex; gap:.8rem; align-items:center; margin-bottom:1.6rem; }
  .topmatter::after { content:""; height:1px; flex:1; background:var(--line); }
  .spine { display:inline-block; background:var(--accent); color:#1a1206; font-family:var(--mono); font-weight:600; font-size:.72rem; letter-spacing:.16em; text-transform:uppercase; padding:.32rem .6rem; border-radius:var(--r-sm); margin-bottom:1.4rem; }
  .hero h1 { font-size:clamp(2.6rem,6.6vw,4.7rem); line-height:1.0; margin:0; max-width:15ch; font-weight:600; }
  .hero h1 em { font-style:italic; font-weight:500; color:var(--ink-soft); }
  .mast-rule { width:72px; height:6px; background:var(--accent); border-radius:3px; margin:1.6rem 0; }
  .hero .lede { font-size:clamp(1.1rem,2.2vw,1.3rem); color:var(--ink-soft); max-width:56ch; margin:0 0 1.8rem; line-height:1.58; }
  .hero .lede strong { color:var(--ink); font-weight:600; }
  .record { font-family:var(--mono); font-size:.8rem; letter-spacing:.02em; color:var(--ink-faint); margin:0 0 2.1rem; line-height:1.9; }
  .record .sep { color:var(--accent-ink); margin:0 .55rem; }
  .hero-actions { display:flex; align-items:center; gap:.85rem 1.3rem; flex-wrap:wrap; }
  .btn { display:inline-flex; align-items:center; gap:.45rem; background:var(--navy); color:var(--paper); text-decoration:none; font-size:.92rem; font-weight:600; padding:.72rem 1.15rem; border-radius:var(--r-sm); box-shadow:var(--shadow-sm); transition:transform .15s ease, box-shadow .15s ease; }
  .btn:hover { transform:translateY(-1px); box-shadow:var(--shadow); }
  .btn:focus-visible { outline:2px solid var(--accent); outline-offset:3px; }
  .cue { color:var(--ink-faint); font-size:.85rem; font-family:var(--mono); max-width:34ch; line-height:1.5; }

  /* ---------- entry (catalog record) layout ---------- */
  .entry { border-top:1px solid var(--line); scroll-margin-top:70px; }
  .entry-grid { display:grid; grid-template-columns:var(--gutter) 1fr; gap:0; }
  .gutter { position:sticky; top:70px; align-self:start; padding:clamp(2.5rem,5.5vw,4rem) 1.4rem clamp(2.5rem,5.5vw,4rem) 0; }
  .idx { display:block; font-family:var(--mono); font-size:2rem; font-weight:600; color:var(--accent-ink); line-height:1; }
  .glabel { display:block; font-family:var(--mono); font-size:.68rem; letter-spacing:.14em; text-transform:uppercase; color:var(--ink-faint); line-height:1.5; margin-top:.5rem; }
  .entry-body { border-left:1px solid var(--line); padding:clamp(2.5rem,5.5vw,4rem) 0 clamp(2.5rem,5.5vw,4rem) clamp(1.5rem,4vw,3.25rem); min-width:0; }
  @media (max-width:820px) {
    .entry-grid { grid-template-columns:1fr; }
    .gutter { position:static; display:flex; align-items:baseline; gap:.7rem; padding:clamp(2rem,6vw,2.5rem) 0 0; }
    .idx { font-size:1.5rem; } .glabel { margin-top:0; }
    .entry-body { border-left:0; padding:1.3rem 0 clamp(2.5rem,7vw,3.25rem); }
  }
  .entry-body h2 { font-size:clamp(1.7rem,3.3vw,2.3rem); margin:0 0 1.1rem; }
  .entry-body > .lead { color:var(--ink-soft); max-width:var(--measure); margin:0 0 1.8rem; }
  .prose { max-width:var(--measure); }
  .prose p { color:var(--ink-soft); margin:0 0 1.1rem; }
  .prose strong { color:var(--ink); font-weight:600; }

  /* facts list (how it works) */
  .facts { list-style:none; margin:2rem 0 0; padding:0; max-width:var(--measure); }
  .facts li { display:flex; gap:.85rem; align-items:baseline; padding:.9rem 0; border-top:1px solid var(--line-soft); }
  .facts li .ic { width:17px; height:17px; position:relative; top:2px; }
  .facts b { font-family:var(--serif); font-weight:600; }
  .facts span { color:var(--ink-soft); }

  /* index list (learning goals) */
  .index { list-style:none; margin:0; padding:0; }
  .index li { display:grid; grid-template-columns:auto 1fr auto; gap:1.1rem; align-items:start; padding:1.2rem 0; border-top:1px solid var(--line-soft); }
  .index li:first-child { border-top:0; padding-top:0; }
  .index .iconbox { width:40px; height:40px; border-radius:9px; background:var(--surface-2); display:grid; place-items:center; }
  .index .iconbox .ic { width:21px; height:21px; }
  .index h3 { font-size:1.18rem; margin:.05rem 0 .25rem; }
  .index p { margin:0; color:var(--ink-soft); font-size:.95rem; line-height:1.5; max-width:54ch; }
  .index .tag { font-family:var(--mono); font-size:.64rem; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-faint); white-space:nowrap; padding-top:.35rem; }
  @media (max-width:520px) { .index li { grid-template-columns:auto 1fr; } .index .tag { display:none; } }

  /* ---------- outcomes band (full-bleed interstitial) ---------- */
  .band { background:var(--navy); color:var(--paper); scroll-margin-top:70px; }
  .band .wrap { padding-block:clamp(2.75rem,6vw,4.25rem); }
  .band .klabel { font-family:var(--mono); font-size:.72rem; letter-spacing:.16em; text-transform:uppercase; color:var(--accent); margin:0 0 .7rem; }
  .band h2 { font-size:clamp(1.7rem,3.4vw,2.4rem); font-style:italic; font-weight:500; margin:0; color:var(--paper); }
  .says { list-style:none; margin:1.8rem 0 0; padding:0; display:grid; grid-template-columns:1fr 1fr; gap:1rem 2.6rem; max-width:62ch; }
  .says li { position:relative; padding-left:1.9rem; font-family:var(--serif); font-size:1.14rem; font-style:italic; line-height:1.4; }
  .says li::before { content:""; position:absolute; left:1px; top:.32em; width:11px; height:6px; border-left:2px solid var(--accent); border-bottom:2px solid var(--accent); transform:rotate(-45deg); }
  @media (max-width:600px) { .says { grid-template-columns:1fr; } }

  /* ---------- course arc ---------- */
  .arc-cap { font-family:var(--mono); font-size:.78rem; color:var(--ink-faint); margin:0 0 1.1rem; }
  .arc-scroll { overflow-x:auto; margin-bottom:2.2rem; padding-bottom:.3rem; }
  svg.arc { width:100%; min-width:680px; height:auto; display:block; }
  .arc .base { stroke:var(--line); stroke-width:2.5; fill:none; }
  .arc .base.dash { stroke-dasharray:1.5 8; stroke-linecap:round; }
  .arc .dot { fill:var(--surface); stroke:var(--ink-faint); stroke-width:2; }
  .arc .mile { fill:var(--accent); }
  .arc .ring { fill:none; stroke:var(--accent); stroke-width:2; opacity:.4; }
  .arc .wklab { fill:var(--ink-faint); font-family:var(--mono); font-size:12px; letter-spacing:.05em; text-anchor:middle; }
  .arc .alab { fill:var(--accent-ink); font-family:var(--mono); font-size:12px; font-weight:600; text-anchor:middle; }
  .arc .plab { fill:var(--ink); font-family:var(--serif); font-size:16px; text-anchor:middle; }
  .arc .pbr { stroke:var(--line); stroke-width:1.5; fill:none; }
  .arc .brk { fill:var(--ink-faint); font-family:var(--mono); font-size:11px; font-style:italic; text-anchor:middle; }

  /* ---------- schedule table (ledger) ---------- */
  .legend { font-family:var(--mono); font-size:.78rem; color:var(--ink-faint); margin:0 0 1.3rem; line-height:1.6; }
  .legend b { color:var(--accent-ink); font-weight:600; }
  .table-scroll { overflow-x:auto; border:1px solid var(--line); border-radius:var(--r-sm); background:var(--surface); }
  table.sched { width:100%; border-collapse:collapse; min-width:640px; font-size:.94rem; }
  table.sched thead th { text-align:left; font-family:var(--mono); font-weight:600; font-size:.66rem; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-faint); padding:.85rem 1.05rem; border-bottom:1px solid var(--line); background:var(--surface-2); position:sticky; top:0; }
  table.sched td { padding:.95rem 1.05rem; border-bottom:1px solid var(--line-soft); vertical-align:middle; }
  table.sched tbody tr:last-child td { border-bottom:0; }
  table.sched tbody tr:hover td { background:color-mix(in srgb,var(--accent-bg) 40%,transparent); }
  .wk { font-family:var(--mono); font-weight:600; color:var(--accent-ink); font-size:.86rem; white-space:nowrap; }
  .topicwrap { display:flex; align-items:center; gap:.65rem; }
  .topic { font-family:var(--serif); font-size:1.04rem; color:var(--ink); }
  .topic .flex { display:inline-block; margin-left:.3rem; color:var(--accent-ink); font-family:var(--sans); font-weight:700; }
  .due { font-family:var(--mono); font-variant-numeric:tabular-nums; color:var(--ink-soft); white-space:nowrap; }
  .chips { display:flex; flex-wrap:wrap; gap:.35rem; }
  .chip { font-size:.73rem; padding:.18rem .5rem; border-radius:3px; border:1px solid var(--line); color:var(--ink-soft); background:var(--surface-2); white-space:nowrap; }
  .chip.assign { border-color:color-mix(in srgb,var(--accent) 55%,var(--line)); color:var(--accent-ink); background:var(--accent-bg); font-weight:600; }
  tr.break td { background:var(--surface-2); }
  tr.break .topic { color:var(--ink-faint); font-style:italic; font-size:.96rem; }
  tr.break .ic { color:var(--ink-faint); }

  /* ---------- assignments (filing cards) ---------- */
  .files { list-style:none; margin:0; padding:0; display:grid; gap:1rem; }
  .files li { display:grid; grid-template-columns:auto 1fr auto; gap:.6rem 1.5rem; align-items:baseline; background:var(--surface-2); border:1px solid var(--line); border-radius:var(--r-sm); padding:1.35rem 1.5rem; }
  .files .fidx { font-family:var(--mono); font-size:2.3rem; font-weight:600; color:var(--accent-ink); line-height:.85; }
  .files .fbody { min-width:0; }
  .files h3 { font-size:1.24rem; margin:.15rem 0 .4rem; }
  .files p { margin:0; color:var(--ink-soft); font-size:.95rem; line-height:1.5; max-width:60ch; }
  .files .fdue { font-family:var(--mono); font-size:.74rem; letter-spacing:.06em; text-transform:uppercase; color:var(--ink-faint); white-space:nowrap; text-align:right; }
  .files li.final { border-color:color-mix(in srgb,var(--accent) 45%,var(--line)); background:var(--accent-bg); }
  @media (max-width:620px) { .files li { grid-template-columns:auto 1fr; } .files .fdue { grid-column:2; text-align:left; padding-top:.4rem; } }

  /* ---------- colophon / contact ---------- */
  .colophon { display:grid; grid-template-columns:1fr 1fr; gap:2rem 2.5rem; }
  @media (max-width:640px) { .colophon { grid-template-columns:1fr; } }
  .cblock { border-top:2px solid var(--ink); padding-top:1.1rem; }
  .cblock h3 { font-size:1.16rem; margin:0 0 1rem; }
  .dl { display:grid; grid-template-columns:auto 1fr; gap:.6rem 1.2rem; margin:0; }
  .dl dt { font-family:var(--mono); font-size:.64rem; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-faint); padding-top:.2rem; }
  .dl dd { margin:0; color:var(--ink); }
  .dl dd a { color:var(--accent-ink); text-decoration:none; }
  .dl dd a:hover { text-decoration:underline; }
  .ph { color:var(--ink-faint); font-style:italic; }
  .note { margin-top:1.5rem; font-family:var(--mono); font-size:.76rem; color:var(--ink-faint); line-height:1.6; }

  footer.site { border-top:1px solid var(--line); }
  footer.site .wrap { padding-block:2.4rem 3rem; display:flex; flex-wrap:wrap; gap:.5rem 1.2rem; align-items:baseline; justify-content:space-between; color:var(--ink-faint); font-family:var(--mono); font-size:.76rem; letter-spacing:.04em; }

  /* reveal */
  .reveal { opacity:0; transform:translateY(12px); animation:rise .7s cubic-bezier(.2,.7,.2,1) forwards; }
  .reveal.d1 { animation-delay:.05s; } .reveal.d2 { animation-delay:.11s; } .reveal.d3 { animation-delay:.17s; } .reveal.d4 { animation-delay:.23s; } .reveal.d5 { animation-delay:.29s; }
  @keyframes rise { to { opacity:1; transform:none; } }
  @media (prefers-reduced-motion:reduce) { .reveal { animation:none; opacity:1; transform:none; } html { scroll-behavior:auto; } }
</style>
</head>
