              <tr><td class="wk">Week 1</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-compass"/></svg><span class="topic">Learning in a Digital &amp; AI Age</span></div></td><td><div class="chips"><span class="chip">Discussion</span><span class="chip">AI / digital tool survey</span></div></td><td class="due">Jan 17</td></tr>
              <tr><td class="wk">Week 2</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-learn"/></svg><span class="topic">Learning How to Learn</span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Jan 24</td></tr>
              <tr><td class="wk">Week 3</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-comms"/></svg><span class="topic">Digital Communication &amp; Collaboration</span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Jan 31</td></tr>
              <tr><td class="wk">Week 4</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-info"/></svg><span class="topic">Information Literacy</span></div></td><td><div class="chips"><span class="chip">Discussion</span><span class="chip assign">Assignment 1</span></div></td><td class="due">Feb 7</td></tr>
              <tr><td class="wk">Week 5</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-ai"/></svg><span class="topic">AI Literacy</span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Feb 14</td></tr>
              <tr><td class="wk">Week 6</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-ethics"/></svg><span class="topic">Ethics, Privacy &amp; Power in an AI Age</span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Feb 21</td></tr>
              <tr><td class="wk">Week 7</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-design"/></svg><span class="topic">Human-Centered Design</span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Feb 28</td></tr>
              <tr><td class="wk">Week 8</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-identity"/></svg><span class="topic">Professional Identity &amp; Self-Presentation</span></div></td><td><div class="chips"><span class="chip">Discussion</span><span class="chip assign">Assignment 2</span></div></td><td class="due">Mar 7</td></tr>
              <tr><td class="wk">Week 9</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-data"/></svg><span class="topic">Working with Data</span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Mar 14</td></tr>
