              <tr><td class="wk">Week 10</td><td><div class="topicwrap"><svg class="ic ic-lg"><use href="#ic-viz"/></svg><span class="topic">Data Storytelling &amp; Visualization <span class="flex" title="Two-week unit">★</span></span></div></td><td><div class="chips"><span class="chip">Discussion</span></div></td><td class="due">Apr 4</td></tr>
