67	  .nav-links a { text-decoration:none; color:var(--ink-soft); font-family:var(--mono); font-size:.78rem; letter-spacing:.04em; padding:.2rem 0; position:relative; transition:color .15s ease; }
68	  .nav-links a .no { color:var(--accent-ink); }
69	  .nav-links a::after { content:""; position:absolute; left:0; right:100%; bottom:-.2rem; height:1.5px; background:var(--accent); transition:right .2s ease; }
70	  .nav-links a:hover { color:var(--ink); }
71	  .nav-links a:hover::after { right:0; }
72	  .nav-links a:focus-visible { outline:2px solid var(--accent); outline-offset:4px; border-radius:2px; }
73	  @media (max-width:820px) { .nav-links { display:none; } }
74	
75	  /* ---------- hero / cover ---------- */
76	  .hero { padding:clamp(2.75rem,7vw,5rem) 0 clamp(2.5rem,6vw,4rem); }
77	  .topmatter { font-family:var(--mono); font-size:.72rem; letter-spacing:.16em; text-transform:uppercase; color:var(--ink-faint); display:flex; gap:.8rem; align-items:center; margin-bottom:1.6rem; }
78	  .topmatter::after { content:""; height:1px; flex:1; background:var(--line); }
79	  .spine { display:inline-block; background:var(--accent); color:#1a1206; font-family:var(--mono); font-weight:600; font-size:.72rem; letter-spacing:.16em; text-transform:uppercase; padding:.32rem .6rem; border-radius:var(--r-sm); margin-bottom:1.4rem; }
80	  .hero h1 { font-size:clamp(2.6rem,6.6vw,4.7rem); line-height:1.0; margin:0; max-width:15ch; font-weight:600; }
81	  .hero h1 em { font-style:italic; font-weight:500; color:var(--ink-soft); }
82	  .mast-rule { width:72px; height:6px; background:var(--accent); border-radius:3px; margin:1.6rem 0; }
83	  .hero .lede { font-size:clamp(1.1rem,2.2vw,1.3rem); color:var(--ink-soft); max-width:56ch; margin:0 0 1.8rem; line-height:1.58; }
84	  .hero .lede strong { color:var(--ink); font-weight:600; }
85	  .record { font-family:var(--mono); font-size:.8rem; letter-spacing:.02em; color:var(--ink-faint); margin:0 0 2.1rem; line-height:1.9; }
86	  .record .sep { color:var(--accent-ink); margin:0 .55rem; }
87	  .hero-actions { display:flex; align-items:center; gap:.85rem 1.3rem; flex-wrap:wrap; }
88	  .btn { display:inline-flex; align-items:center; gap:.45rem; background:var(--navy); color:var(--paper); text-decoration:none; font-size:.92rem; font-weight:600; padding:.72rem 1.15rem; border-radius:var(--r-sm); box-shadow:var(--shadow-sm); transition:transform .15s ease, box-shadow .15s ease; }
89	  .btn:hover { transform:translateY(-1px); box-shadow:var(--shadow); }
90	  .btn:focus-visible { outline:2px solid var(--accent); outline-offset:3px; }
91	  .cue { color:var(--ink-faint); font-size:.85rem; font-family:var(--mono); max-width:34ch; line-height:1.5; }
92	
93	  /* ---------- entry (catalog record) layout ---------- */
94	  .entry { border-top:1px solid var(--line); scroll-margin-top:70px; }
95	  .entry-grid { display:grid; grid-template-columns:var(--gutter) 1fr; gap:0; }
96	  .gutter { position:sticky; top:70px; align-self:start; padding:clamp(2.5rem,5.5vw,4rem) 1.4rem clamp(2.5rem,5.5vw,4rem) 0; }
97	  .idx { display:block; font-family:var(--mono); font-size:2rem; font-weight:600; color:var(--accent-ink); line-height:1; }
98	  .glabel { display:block; font-family:var(--mono); font-size:.68rem; letter-spacing:.14em; text-transform:uppercase; color:var(--ink-faint); line-height:1.5; margin-top:.5rem; }
99	  .entry-body { border-left:1px solid var(--line); padding:clamp(2.5rem,5.5vw,4rem) 0 clamp(2.5rem,5.5vw,4rem) clamp(1.5rem,4vw,3.25rem); min-width:0; }
100	  @media (max-width:820px) {
101	    .entry-grid { grid-template-columns:1fr; }
102	    .gutter { position:static; display:flex; align-items:baseline; gap:.7rem; padding:clamp(2rem,6vw,2.5rem) 0 0; }
103	    .idx { font-size:1.5rem; } .glabel { margin-top:0; }
104	    .entry-body { border-left:0; padding:1.3rem 0 clamp(2.5rem,7vw,3.25rem); }
105	  }
106	  .entry-body h2 { font-size:clamp(1.7rem,3.3vw,2.3rem); margin:0 0 1.1rem; }
107	  .entry-body > .lead { color:var(--ink-soft); max-width:var(--measure); margin:0 0 1.8rem; }
108	  .prose { max-width:var(--measure); }
109	  .prose p { color:var(--ink-soft); margin:0 0 1.1rem; }
110	  .prose strong { color:var(--ink); font-weight:600; }
111	
112	  /* facts list (how it works) */
113	  .facts { list-style:none; margin:2rem 0 0; padding:0; max-width:var(--measure); }
114	  .facts li { display:flex; gap:.85rem; align-items:baseline; padding:.9rem 0; border-top:1px solid var(--line-soft); }
115	  .facts li .ic { width:17px; height:17px; position:relative; top:2px; }
116	  .facts b { font-family:var(--serif); font-weight:600; }
117	  .facts span { color:var(--ink-soft); }
118	
119	  /* index list (learning goals) */
120	  .index { list-style:none; margin:0; padding:0; }
121	  .index li { display:grid; grid-template-columns:auto 1fr auto; gap:1.1rem; align-items:start; padding:1.2rem 0; border-top:1px solid var(--line-soft); }
122	  .index li:first-child { border-top:0; padding-top:0; }
123	  .index .iconbox { width:40px; height:40px; border-radius:9px; background:var(--surface-2); display:grid; place-items:center; }
124	  .index .iconbox .ic { width:21px; height:21px; }
125	  .index h3 { font-size:1.18rem; margin:.05rem 0 .25rem; }
126	  .index p { margin:0; color:var(--ink-soft); font-size:.95rem; line-height:1.5; max-width:54ch; }
127	  .index .tag { font-family:var(--mono); font-size:.64rem; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-faint); white-space:nowrap; padding-top:.35rem; }
128	  @media (max-width:520px) { .index li { grid-template-columns:auto 1fr; } .index .tag { display:none; } }
129	
130	  /* ---------- course arc ---------- */

130	  /* ---------- course arc ---------- */
131	  .arc-cap { font-family:var(--mono); font-size:.78rem; color:var(--ink-faint); margin:0 0 1.1rem; }
132	  .arc-scroll { overflow-x:auto; margin-bottom:2.2rem; padding-bottom:.3rem; }
133	  svg.arc { width:100%; min-width:680px; height:auto; display:block; }
134	  .arc .base { stroke:var(--line); stroke-width:2.5; fill:none; }
135	  .arc .base.dash { stroke-dasharray:1.5 8; stroke-linecap:round; }
136	  .arc .dot { fill:var(--surface); stroke:var(--ink-faint); stroke-width:2; }
137	  .arc .mile { fill:var(--accent); }
138	  .arc .ring { fill:none; stroke:var(--accent); stroke-width:2; opacity:.4; }
139	  .arc .wklab { fill:var(--ink-faint); font-family:var(--mono); font-size:12px; letter-spacing:.05em; text-anchor:middle; }
140	  .arc .alab { fill:var(--accent-ink); font-family:var(--mono); font-size:12px; font-weight:600; text-anchor:middle; }
141	  .arc .plab { fill:var(--ink); font-family:var(--serif); font-size:16px; text-anchor:middle; }
142	  .arc .pbr { stroke:var(--line); stroke-width:1.5; fill:none; }
143	  .arc .brk { fill:var(--ink-faint); font-family:var(--mono); font-size:11px; font-style:italic; text-anchor:middle; }
144	
145	  /* ---------- schedule table (ledger) ---------- */
146	  .legend { font-family:var(--mono); font-size:.78rem; color:var(--ink-faint); margin:0 0 1.3rem; line-height:1.6; }
147	  .legend b { color:var(--accent-ink); font-weight:600; }
148	  .table-scroll { overflow-x:auto; border:1px solid var(--line); border-radius:var(--r-sm); background:var(--surface); }
149	  table.sched { width:100%; border-collapse:collapse; min-width:640px; font-size:.94rem; }
150	  table.sched thead th { text-align:left; font-family:var(--mono); font-weight:600; font-size:.66rem; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-faint); padding:.85rem 1.05rem; border-bottom:1px solid var(--line); background:var(--surface-2); position:sticky; top:0; }
151	  table.sched td { padding:.95rem 1.05rem; border-bottom:1px solid var(--line-soft); vertical-align:middle; }
152	  table.sched tbody tr:last-child td { border-bottom:0; }
153	  table.sched tbody tr:hover td { background:color-mix(in srgb,var(--accent-bg) 40%,transparent); }
154	  .wk { font-family:var(--mono); font-weight:600; color:var(--accent-ink); font-size:.86rem; white-space:nowrap; }
155	  .topicwrap { display:flex; align-items:center; gap:.65rem; }
156	  .topic { font-family:var(--serif); font-size:1.04rem; color:var(--ink); }
157	  .topic .flex { display:inline-block; margin-left:.3rem; color:var(--accent-ink); font-family:var(--sans); font-weight:700; }
158	  .due { font-family:var(--mono); font-variant-numeric:tabular-nums; color:var(--ink-soft); white-space:nowrap; }
159	  .chips { display:flex; flex-wrap:wrap; gap:.35rem; }
160	  .chip { font-size:.73rem; padding:.18rem .5rem; border-radius:3px; border:1px solid var(--line); color:var(--ink-soft); background:var(--surface-2); white-space:nowrap; }
161	  .chip.assign { border-color:color-mix(in srgb,var(--accent) 55%,var(--line)); color:var(--accent-ink); background:var(--accent-bg); font-weight:600; }
162	  tr.break td { background:var(--surface-2); }
163	  tr.break .topic { color:var(--ink-faint); font-style:italic; font-size:.96rem; }
164	  tr.break .ic { color:var(--ink-faint); }
165	
166	  /* ---------- assignments (filing cards) ---------- */
167	  .files { list-style:none; margin:0; padding:0; display:grid; gap:1rem; }
168	  .files li { display:grid; grid-template-columns:auto 1fr auto; gap:.6rem 1.5rem; align-items:baseline; background:var(--surface-2); border:1px solid var(--line); border-radius:var(--r-sm); padding:1.35rem 1.5rem; }
169	  .files .fidx { font-family:var(--mono); font-size:2.3rem; font-weight:600; color:var(--accent-ink); line-height:.85; }
170	  .files .fbody { min-width:0; }
171	  .files h3 { font-size:1.24rem; margin:.15rem 0 .4rem; }
172	  .files p { margin:0; color:var(--ink-soft); font-size:.95rem; line-height:1.5; max-width:60ch; }
173	  .files .fdue { font-family:var(--mono); font-size:.74rem; letter-spacing:.06em; text-transform:uppercase; color:var(--ink-faint); white-space:nowrap; text-align:right; }
174	  .files li.final { border-color:color-mix(in srgb,var(--accent) 45%,var(--line)); background:var(--accent-bg); }
175	  @media (max-width:620px) { .files li { grid-template-columns:auto 1fr; } .files .fdue { grid-column:2; text-align:left; padding-top:.4rem; } }
176	
177	  /* ---------- colophon / contact ---------- */
178	  .colophon { display:grid; grid-template-columns:1fr 1fr; gap:2rem 2.5rem; }
179	  @media (max-width:640px) { .colophon { grid-template-columns:1fr; } }
180	  .cblock { border-top:2px solid var(--ink); padding-top:1.1rem; }
181	  .cblock h3 { font-size:1.16rem; margin:0 0 1rem; }
182	  .dl { display:grid; grid-template-columns:auto 1fr; gap:.6rem 1.2rem; margin:0; }
183	  .dl dt { font-family:var(--mono); font-size:.64rem; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-faint); padding-top:.2rem; }
184	  .dl dd { margin:0; color:var(--ink); }
185	  .dl dd a { color:var(--accent-ink); text-decoration:none; }
186	  .dl dd a:hover { text-decoration:underline; }
187	  .ph { color:var(--ink-faint); font-style:italic; }
188	  .note { margin-top:1.5rem; font-family:var(--mono); font-size:.76rem; color:var(--ink-faint); line-height:1.6; }
189	
190	  footer.site { border-top:1px solid var(--line); }
191	  footer.site .wrap { padding-block:2.4rem 3rem; display:flex; flex-wrap:wrap; gap:.5rem 1.2rem; align-items:baseline; justify-content:space-between; color:var(--ink-faint); font-family:var(--mono); font-size:.76rem; letter-spacing:.04em; }
192	
193	  /* reveal */
194	  .reveal { opacity:0; transform:translateY(12px); animation:rise .7s cubic-bezier(.2,.7,.2,1) forwards; }
195	  .reveal.d1 { animation-delay:.05s; } .reveal.d2 { animation-delay:.11s; } .reveal.d3 { animation-delay:.17s; } .reveal.d4 { animation-delay:.23s; } .reveal.d5 { animation-delay:.29s; }
196	  @keyframes rise { to { opacity:1; transform:none; } }
197	  @media (prefers-reduced-motion:reduce) { .reveal { animation:none; opacity:1; transform:none; } html { scroll-behavior:auto; } }
198	</style>
